/* THE MAGNET REGISTRY — the only node a new lead magnet touches.
 *
 * Adding a magnet is ONE entry here plus a capture form on the page. No new
 * webhook, no new Caddy route, no new Twenty enum value, no second workflow.
 * That is the whole reason this endpoint is generic: plan-lead and
 * zone-workouts are two near-identical copies of the same six nodes, and a
 * third copy was the alternative to this file.
 *
 * Repo mirror: automation/tool-lead-workflow.json. n8n is the live source;
 * edit here, then mirror the change into the repo copy in the same session.
 *
 * Execution mode is Run Once for Each Item, set explicitly. A webhook delivers
 * one item today; the standing rule exists because a node written single-item
 * style misbehaves silently the first time an execution carries two.
 */

const MAGNETS = {
  runner_week: {
    // Twenty leadSource stays TOOL_LEAD for every magnet, on purpose: a value
    // per magnet turns one enum into a growing list Ivan has to maintain in the
    // Twenty UI, which is the manual step this endpoint exists to remove.
    // Which magnet it was lives in leadNotes and in the magnet key below.
    noteLabel: 'Guia "La semana de fuerza del corredor" (core de corredor publico)',
    pdf: {
      es: 'https://triaperformance.com/assets/guias/semana-de-fuerza-del-corredor.pdf',
      en: 'https://triaperformance.com/assets/guias/runner-strength-week.pdf',
      pt: 'https://triaperformance.com/assets/guias/semana-de-forca-do-corredor.pdf',
    },
    offer: {
      es: 'https://triaperformance.com/all-access/',
      en: 'https://triaperformance.com/en/all-access/',
      pt: 'https://triaperformance.com/pt/all-access/',
    },
    price: { es: '39,99', en: '39.99', pt: '29,99' },
    subject: {
      es: 'Tu semana de fuerza',
      en: 'Your strength week',
      pt: 'Sua semana de força',
    },
    body: {
      es: (m, lang) => [
        'Hola,',
        '',
        'Aquí está la guía: dónde entran esas dos sesiones de core en tu semana, y las tres cosas que la rutina no entrena.',
        '',
        m.pdf[lang],
        '',
        'Adentro está la dosis (dos veces por semana, en días fáciles, nunca antes de una sesión de calidad), las cuatro reglas que deciden dónde va el gimnasio, una semana completa con esas reglas aplicadas, y qué hacer cuando algo duele.',
        '',
        'Un aviso que está en la guía y que prefiero repetir aquí: el circuito que hiciste no entrena el resorte del pie y del gemelo, ni el seguimiento de la rótula bajo carga, ni la espalda alta. Los tres están explicados adentro, con qué hacer al respecto.',
        '',
        'Si prefieres que la semana ya venga escrita, eso es lo que hace la membresía All-Access: todo el catálogo de planes más la biblioteca de herramientas, por US$ ' + m.price[lang] + ' al mes.',
        m.offer[lang],
        '',
        'Cualquier duda, responde a este mismo mail.',
        '',
        'Iván Koch — Triaperformance',
      ].join('\n'),
      en: (m, lang) => [
        'Hi,',
        '',
        'Here is the guide: where those two core sessions go in your week, and the three things the routine does not train.',
        '',
        m.pdf[lang],
        '',
        'Inside you will find the dose (twice a week, on easy days, never before a quality session), the four rules that decide where the gym goes, a full week with those rules applied, and what to do when something hurts.',
        '',
        'One warning that is in the guide and that I would rather repeat here: the circuit you just did does not train the foot and calf spring, kneecap tracking under load, or the upper back. All three are explained inside, with what to do about them.',
        '',
        'If you would rather the week came already written, that is what the All-Access membership does: the whole plan catalogue plus the tools library, for US$ ' + m.price[lang] + ' a month.',
        m.offer[lang],
        '',
        'Any questions, just reply to this email.',
        '',
        'Iván Koch — Triaperformance',
      ].join('\n'),
      pt: (m, lang) => [
        'Olá,',
        '',
        'Aqui está o guia: onde entram essas duas sessões de core na sua semana, e as três coisas que a rotina não treina.',
        '',
        m.pdf[lang],
        '',
        'Lá dentro está a dose (duas vezes por semana, em dias leves, nunca antes de uma sessão de qualidade), as quatro regras que decidem onde entra a academia, uma semana completa com essas regras aplicadas, e o que fazer quando algo dói.',
        '',
        'Um aviso que está no guia e que prefiro repetir aqui: o circuito que você fez não treina a mola do pé e da panturrilha, nem o rastreamento da patela sob carga, nem a parte alta das costas. Os três estão explicados lá dentro, com o que fazer a respeito.',
        '',
        'Se você prefere que a semana já venha escrita, é isso que a assinatura All-Access faz: todo o catálogo de planos mais a biblioteca de ferramentas, por US$ ' + m.price[lang] + ' por mês.',
        m.offer[lang],
        '',
        'Qualquer dúvida, responda a este mesmo email.',
        '',
        'Iván Koch — Triaperformance',
      ].join('\n'),
    },
  },
};

/* The footer every send carries. unsubscribe-runbook.md §Footer copy: never
 * omit it to make a message feel more personal, and name the reason they are
 * hearing from you — that is the half that reduces complaints. The reason
 * differs from the CoachMatch footer because the reason really is different:
 * they asked for a guide on the website, not about coaching on TrainingPeaks. */
const FOOTER = {
  es: 'Recibes este correo porque pediste la guía en triaperformance.com.\nSi no quieres recibir más, date de baja aquí:',
  en: 'You are receiving this because you asked for the guide on triaperformance.com.\nIf you would rather not hear from me, unsubscribe here:',
  pt: 'Você recebe este email porque pediu o guia em triaperformance.com.\nSe preferir não receber mais, descadastre-se aqui:',
};

const LANG_ENUM = { es: 'SPANISH', en: 'ENGLISH', pt: 'PORTUGUESE' };

const body = $json.body || {};
const email = String(body.email || '').trim().toLowerCase();
const magnetKey = String(body.magnet || '').trim();
const lang = (LANG_ENUM[body.language] ? body.language : 'es');

/* Fail loudly on a bad payload rather than minting a token and mailing nobody.
 * A magnet key that is not in the registry is the likely mistake: a page shipped
 * with a form before its entry was added here. */
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  throw new Error('tool-lead: invalid or missing email in payload');
}
const m = MAGNETS[magnetKey];
if (!m) {
  throw new Error('tool-lead: unknown magnet "' + magnetKey + '" — add it to the registry in this node');
}

return {
  json: {
    email: email,
    magnet: magnetKey,
    lang: lang,
    langEnum: LANG_ENUM[lang],
    subject: m.subject[lang] || m.subject.es,
    emailBody: (m.body[lang] || m.body.es)(m, lang),
    footerPrefix: FOOTER[lang] || FOOTER.es,
    pdf: m.pdf[lang] || m.pdf.es,
    leadNotes: m.noteLabel + '. Idioma: ' + lang + '. Pagina: ' + (body.page_url || 'n/a'),
    pageUrl: body.page_url || '',
  },
};

parameters.query:
SELECT 1 AS suppressed
FROM email_suppression
WHERE lower(email) = lower($1);

